set local lock_timeout = '5s';

-- ---- 1. Le lot, en table temporaire ---------------------------------------------------
drop table if exists pg_temp._plc_modeles;
create temporary table _plc_modeles (
	id uuid primary key,
	branche text not null, notion text not null, sous_notion text,
	grades text[] not null,
	tag_grade text not null, tag_code text not null,
	avant jsonb not null, apres jsonb not null
);
insert into _plc_modeles values ('227f2c9c-3494-412d-bf88-e9b2c48c01a6', $plc$Fonctions$plc$, $plc$Fonction exponentielle$plc$, $plc$dérivée$plc$, array['1_SPE'], '1_SPE', '1SPE-295',
  $plc${"title":"Dériver une exponentielle de fonction affine","description":"Dérivée de l'exponentielle d'une fonction affine : (e^(ax+b))′ = a·e^(ax+b)","variations":[{"blanks":[{"expectedAnswer":"{{a}}e^{ {{eval:a*x+b}} }"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)=e^{ {{eval:a*x+b}} }$.\n\nCalcule $f'(x)$.\n\n$f'(x)=?$","variables":[{"name":"x","expression":"x|x"},{"name":"a","expression":"2..6;±"},{"name":"b","expression":"1..7;±"}],"correction":{"steps":["Pour toute fonction affine $u$, la dérivée de $x\\mapsto e^{u(x)}$ est $x\\mapsto u'(x)\\,e^{u(x)}$ : le coefficient de $x$ **passe devant** l'exponentielle.","Ici $u(x)={{eval:a*x+b}}$, donc $u'(x)=\\textcolor{{{color:primary.0}}}{ {{a}} }$ et $f'(x)=\\textcolor{{{color:primary.0}}}{ {{a}} }e^{ {{eval:a*x+b}} }$."]}},{"blanks":[{"expectedAnswer":"-e^{ {{eval:-x+b}} }"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)=e^{ {{eval:-x+b}} }$.\n\nCalcule $f'(x)$.\n\n$f'(x)=?$","variables":[{"name":"x","expression":"x|x"},{"name":"b","expression":"1..7;±"}],"correction":{"steps":["Pour toute fonction affine $u$, la dérivée de $x\\mapsto e^{u(x)}$ est $x\\mapsto u'(x)\\,e^{u(x)}$ : le coefficient de $x$ **passe devant** l'exponentielle.","Ici $u(x)={{eval:-x+b}}$, donc $u'(x)=\\textcolor{{{color:primary.0}}}{-1}$ et $f'(x)=\\textcolor{{{color:primary.0}}}{-1}\\times e^{ {{eval:-x+b}} }=-e^{ {{eval:-x+b}} }$."]}},{"blanks":[{"expectedAnswer":"{{a}}e^{ {{eval:a*x}} }"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)=e^{ {{eval:a*x}} }$.\n\nCalcule $f'(x)$.\n\n$f'(x)=?$","variables":[{"name":"x","expression":"x|x"},{"name":"a","expression":"2..9;±"}],"correction":{"steps":["Pour toute fonction affine $u$, la dérivée de $x\\mapsto e^{u(x)}$ est $x\\mapsto u'(x)\\,e^{u(x)}$ : le coefficient de $x$ **passe devant** l'exponentielle.","Ici $u(x)={{eval:a*x}}$, donc $u'(x)=\\textcolor{{{color:primary.0}}}{ {{a}} }$ et $f'(x)=\\textcolor{{{color:primary.0}}}{ {{a}} }e^{ {{eval:a*x}} }$."]}}],"shared":null,"test_specs":[{"answers":["3e^{3x-2}"],"expected":{"status":"correct"},"variables":{"a":"3","b":"-2"},"description":"3e^{3x-2} juste","variationIndex":0},{"answers":["3e^{-2+3x}"],"expected":{"status":"correct"},"variables":{"a":"3","b":"-2"},"description":"exposant écrit −2+3x","variationIndex":0},{"answers":["e^{3x-2}"],"expected":{"status":"incorrect"},"variables":{"a":"3","b":"-2"},"description":"oubli du facteur a : e^{3x−2}","variationIndex":0},{"answers":["e^{3}"],"expected":{"status":"incorrect"},"variables":{"a":"3","b":"-2"},"description":"u′ mis dans l'exposant : e^{3}","variationIndex":0},{"answers":["(3x-2)e^{3x-2}"],"expected":{"status":"incorrect"},"variables":{"a":"3","b":"-2"},"description":"u multiplié : (3x−2)e^{3x−2}","variationIndex":0},{"answers":["(3x-2)e^{3x-3}"],"expected":{"status":"incorrect"},"variables":{"a":"3","b":"-2"},"description":"règle de x^n : (3x−2)e^{3x−3}","variationIndex":0},{"answers":["e^{3x-2}\\times3"],"expected":{"status":"unoptimal_form","constraintViolations":["products"]},"variables":{"a":"3","b":"-2"},"description":"facteur écrit derrière avec × (½, products)","variationIndex":0},{"answers":["3e^{3x}e^{-2}"],"expected":{"status":"bad_form","constraintViolations":["form"]},"variables":{"a":"3","b":"-2"},"description":"exponentielle scindée 3e^{3x}e^{−2} (forme)","variationIndex":0},{"answers":["-4e^{-4x+5}"],"expected":{"status":"correct"},"variables":{"a":"-4","b":"5"},"description":"a < 0 : −4e^{−4x+5}","variationIndex":0},{"answers":["-4e^{5-4x}"],"expected":{"status":"correct"},"variables":{"a":"-4","b":"5"},"description":"a < 0, exposant 5−4x","variationIndex":0},{"answers":["4e^{-4x+5}"],"expected":{"status":"incorrect"},"variables":{"a":"-4","b":"5"},"description":"a < 0, signe oublié : 4e^{−4x+5}","variationIndex":0},{"answers":["-e^{-x+3}"],"expected":{"status":"correct"},"variables":{"b":"3"},"description":"e^{−x+3} : −e^{−x+3}","variationIndex":1},{"answers":["-e^{3-x}"],"expected":{"status":"correct"},"variables":{"b":"3"},"description":"exposant écrit 3−x","variationIndex":1},{"answers":["e^{-x+3}"],"expected":{"status":"incorrect"},"variables":{"b":"3"},"description":"signe oublié : e^{−x+3}","variationIndex":1},{"answers":["-1e^{-x+3}"],"expected":{"status":"unoptimal_form","constraintViolations":["factorOne"]},"variables":{"b":"3"},"description":"−1 laissé en facteur (½, factorOne)","variationIndex":1},{"answers":["5e^{5x}"],"expected":{"status":"correct"},"variables":{"a":"5"},"description":"e^{5x} : 5e^{5x}","variationIndex":2},{"answers":["e^{5x}"],"expected":{"status":"incorrect"},"variables":{"a":"5"},"description":"oubli du facteur : e^{5x}","variationIndex":2},{"answers":["5xe^{5x-1}"],"expected":{"status":"incorrect"},"variables":{"a":"5"},"description":"dérivée prise comme 5xe^{5x−1}","variationIndex":2},{"answers":["-2e^{-2x}"],"expected":{"status":"correct"},"variables":{"a":"-2"},"description":"e^{−2x} : −2e^{−2x}","variationIndex":2},{"answers":["2e^{-2x}"],"expected":{"status":"incorrect"},"variables":{"a":"-2"},"description":"e^{−2x} : signe oublié","variationIndex":2},{"answers":["3\\exp(3x-2)"],"expected":{"status":"correct"},"variables":{"a":"3","b":"-2"},"description":"notation 3\\exp acceptée (décision du 2026-10-02)","variationIndex":0},{"answers":["3\\exponentialE^{3x-2}"],"expected":{"status":"correct"},"variables":{"a":"3","b":"-2"},"description":"notation 3\\exponentialE acceptée (décision du 2026-10-02)","variationIndex":0}]}$plc$::jsonb,
  $plc${"title":"Dériver une exponentielle de fonction affine","description":"Dériver x ↦ e^(ax+b) en l'écrivant e^(ax) × e^b : (e^(ax))′ = a·e^(ax)","variations":[{"blanks":[{"expectedAnswer":"{{a}}e^{ {{eval:a*x+b}} }"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)=e^{ {{eval:a*x+b}} }$.\n\nCalcule $f'(x)$.\n\n$f'(x)=?$","variables":[{"name":"x","expression":"x|x"},{"name":"a","expression":"2..6;±"},{"name":"b","expression":"1..7;±"}],"correction":{"steps":["On écrit $f(x)=e^{ {{eval:a*x}} }\\times e^{ {{b}} }$, car $e^{u+v}=e^u\\times e^v$ ; $e^{ {{b}} }$ est une constante.","La dérivée de $x\\mapsto e^{ax}$ est $x\\mapsto a\\,e^{ax}$ : le coefficient de $x$ **passe devant** l'exponentielle.","Donc $f'(x)=\\textcolor{{{color:primary.0}}}{ {{a}} }e^{ {{eval:a*x}} }\\times e^{ {{b}} }=\\textcolor{{{color:primary.0}}}{ {{a}} }e^{ {{eval:a*x+b}} }$."]}},{"blanks":[{"expectedAnswer":"-e^{ {{eval:-x+b}} }"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)=e^{ {{eval:-x+b}} }$.\n\nCalcule $f'(x)$.\n\n$f'(x)=?$","variables":[{"name":"x","expression":"x|x"},{"name":"b","expression":"1..7;±"}],"correction":{"steps":["On écrit $f(x)=e^{-x}\\times e^{ {{b}} }$, car $e^{u+v}=e^u\\times e^v$ ; $e^{ {{b}} }$ est une constante.","La dérivée de $x\\mapsto e^{ax}$ est $x\\mapsto a\\,e^{ax}$ : le coefficient de $x$ **passe devant** l'exponentielle.","Ici $a=\\textcolor{{{color:primary.0}}}{-1}$, donc $f'(x)=-e^{-x}\\times e^{ {{b}} }=-e^{ {{eval:-x+b}} }$."]}},{"blanks":[{"expectedAnswer":"{{a}}e^{ {{eval:a*x}} }"}],"statement":"Soit $f$ la fonction définie sur $\\mathbb{R}$ par $f(x)=e^{ {{eval:a*x}} }$.\n\nCalcule $f'(x)$.\n\n$f'(x)=?$","variables":[{"name":"x","expression":"x|x"},{"name":"a","expression":"2..9;±"}],"correction":{"steps":["La dérivée de $x\\mapsto e^{ax}$ est $x\\mapsto a\\,e^{ax}$ : le coefficient de $x$ **passe devant** l'exponentielle.","Ici $a=\\textcolor{{{color:primary.0}}}{ {{a}} }$, donc $f'(x)=\\textcolor{{{color:primary.0}}}{ {{a}} }e^{ {{eval:a*x}} }$."]}}],"shared":null,"test_specs":[{"answers":["3e^{3x-2}"],"expected":{"status":"correct"},"variables":{"a":"3","b":"-2"},"description":"3e^{3x-2} juste","variationIndex":0},{"answers":["3e^{-2+3x}"],"expected":{"status":"correct"},"variables":{"a":"3","b":"-2"},"description":"exposant écrit −2+3x","variationIndex":0},{"answers":["e^{3x-2}"],"expected":{"status":"incorrect"},"variables":{"a":"3","b":"-2"},"description":"oubli du facteur a : e^{3x−2}","variationIndex":0},{"answers":["e^{3}"],"expected":{"status":"incorrect"},"variables":{"a":"3","b":"-2"},"description":"u′ mis dans l'exposant : e^{3}","variationIndex":0},{"answers":["(3x-2)e^{3x-2}"],"expected":{"status":"incorrect"},"variables":{"a":"3","b":"-2"},"description":"u multiplié : (3x−2)e^{3x−2}","variationIndex":0},{"answers":["(3x-2)e^{3x-3}"],"expected":{"status":"incorrect"},"variables":{"a":"3","b":"-2"},"description":"règle de x^n : (3x−2)e^{3x−3}","variationIndex":0},{"answers":["e^{3x-2}\\times3"],"expected":{"status":"unoptimal_form","constraintViolations":["products"]},"variables":{"a":"3","b":"-2"},"description":"facteur écrit derrière avec × (½, products)","variationIndex":0},{"answers":["3e^{3x}e^{-2}"],"expected":{"status":"bad_form","constraintViolations":["form"]},"variables":{"a":"3","b":"-2"},"description":"exponentielle scindée 3e^{3x}e^{−2} (forme)","variationIndex":0},{"answers":["-4e^{-4x+5}"],"expected":{"status":"correct"},"variables":{"a":"-4","b":"5"},"description":"a < 0 : −4e^{−4x+5}","variationIndex":0},{"answers":["-4e^{5-4x}"],"expected":{"status":"correct"},"variables":{"a":"-4","b":"5"},"description":"a < 0, exposant 5−4x","variationIndex":0},{"answers":["4e^{-4x+5}"],"expected":{"status":"incorrect"},"variables":{"a":"-4","b":"5"},"description":"a < 0, signe oublié : 4e^{−4x+5}","variationIndex":0},{"answers":["-e^{-x+3}"],"expected":{"status":"correct"},"variables":{"b":"3"},"description":"e^{−x+3} : −e^{−x+3}","variationInd