insert into _plc_modeles values ('293f8225-0268-48bc-8487-52c6bf5b01e3', $plc$Nombres complexes$plc$, $plc$Équations polynomiales$plc$, $plc$racines d'un polynôme$plc$, array['T_EXP'], 'T_EXP', 'TEXP-246',
  $plc${"title":"Racines d'un polynôme : compter les solutions, compléter par conjugaison","description":"Compléter les racines d'un polynôme réel de degré 4 connaissant deux racines non conjuguées, compter les solutions dans ℂ et dans ℝ de (z − r)(z² + q) = 0, solutions distinctes avec une racine double, racines restantes au plus (pièges : opposé au lieu du conjugué, solutions de z² + q = 0 comptées réelles, racine double comptée deux fois)","variations":[{"blanks":[{"expectedAnswer":"{{a}}-{{b}}i"},{"expectedAnswer":"-{{c}}i"}],"statement":"$P$ est un polynôme de degré $4$ à coefficients réels tel que $P({{a}}+{{b}}i) = 0$ et $P({{c}}i) = 0$.\n\nDonne ses deux autres racines (dans l'ordre que tu veux).\n\n$z_3=?$ et $z_4=?$","variables":[{"name":"a","expression":"1..4;±"},{"name":"b","expression":"2..4"},{"name":"c","expression":"2..5"}],"conditions":["b != c"],"correction":{"steps":["Les coefficients sont réels : les conjugués ${{a}}-{{b}}i$ et $-{{c}}i$ sont aussi racines.","$P$ est de degré $4$, il a au plus $4$ racines : ce sont ${{a}}+{{b}}i$, $\\textcolor{{{color:primary.0}}}{{{a}}-{{b}}i}$, ${{c}}i$ et $\\textcolor{{{color:primary.0}}}{-{{c}}i}$."]}},{"blanks":[{"expectedAnswer":"3"},{"expectedAnswer":"1"}],"statement":"On considère $P(z) = (z-({{r}}))(z^2+{{q}})$.\n\nNombre de solutions de $P(z) = 0$ dans $\\mathbb{C}$ : $?$\n\nNombre de solutions de $P(z) = 0$ dans $\\mathbb{R}$ : $?$","variables":[{"name":"r","expression":"1..6;±"},{"name":"q","expression":"1..12"}],"correction":{"steps":["$z-({{r}}) = 0$ donne $z = {{r}}$, réel.","$z^2 = -{{q}} < 0$ donne deux solutions non réelles, $\\pm i\\sqrt{ {{q}} }$.","Dans $\\mathbb{C}$ : $\\textcolor{{{color:primary.0}}}{3}$ solutions (autant que le degré) ; dans $\\mathbb{R}$ : $\\textcolor{{{color:primary.0}}}{1}$."]}},{"blanks":[{"expectedAnswer":"4"},{"expectedAnswer":"3"}],"statement":"On considère $P(z) = (z-({{r}}))^2(z^2+{{q}})$.\n\nDegré de $P$ : $?$\n\nNombre de solutions DISTINCTES de $P(z) = 0$ dans $\\mathbb{C}$ : $?$","variables":[{"name":"r","expression":"1..6;±"},{"name":"q","expression":"1..12"}],"correction":{"steps":["$P$ est le produit d'un polynôme de degré $2$ par un polynôme de degré $2$ : degré $\\textcolor{{{color:primary.0}}}{4}$.","Solutions : ${{r}}$ (racine double, comptée une fois) et $\\pm i\\sqrt{ {{q}} }$, soit $\\textcolor{{{color:primary.0}}}{3}$ solutions distinctes : au plus $4$, pas forcément $4$."]}},{"blanks":[{"expectedAnswer":"{{eval:n-k}}"}],"statement":"$P$ est un polynôme de degré ${{n}}$. On connaît déjà ${{k}}$ racines distinctes de $P$.\n\nCombien de racines distinctes, au plus, $P$ peut-il avoir en dehors de celles-ci ?\n\n$?$","variables":[{"name":"n","expression":"4..9"},{"name":"k","expression":"1..5"}],"conditions":["k < n"],"correction":{"steps":["$P$ est de degré ${{n}}$ : il a au plus ${{n}}$ racines distinctes.","Il en reste au plus ${{n}} - {{k}} = \\textcolor{{{color:primary.0}}}{{{eval:n-k}}}$."]}}],"shared":{"genericFunctions":["P"],"cleanCoefficients":true},"test_specs":[{"answers":["2-3i","-4i"],"expected":{"status":"correct"},"variables":{"a":"2","b":"3","c":"4"},"description":"v0 : 2 + 3i et 4i → 2 − 3i, −4i","variationIndex":0},{"answers":["-4i","2-3i"],"expected":{"status":"correct"},"variables":{"a":"2","b":"3","c":"4"},"description":"v0 : dans l'autre ordre","variationIndex":0},{"answers":["-2-3i","-4i"],"expected":{"status":"incorrect"},"variables":{"a":"2","b":"3","c":"4"},"description":"v0 : opposé au lieu du conjugué","variationIndex":0},{"answers":["2+3i","4i"],"expected":{"status":"incorrect"},"variables":{"a":"2","b":"3","c":"4"},"description":"v0 : racines déjà connues recopiées","variationIndex":0},{"answers":["-1-2i","-3i"],"expected":{"status":"correct"},"variables":{"a":"-1","b":"2","c":"3"},"description":"v0 : −1 + 2i et 3i → −1 − 2i, −3i","variationIndex":0},{"answers":["3","1"],"expected":{"status":"correct"},"variables":{"q":"4","r":"-2"},"description":"v1 : 3 et 1","variationIndex":1},{"